import{c as s,$ as i,Q as e,j as a,m as n,h,ax as o,n as d,o as l,S as p}from"./chunks/framework.BqPkuuVc.js";const g="/assets/splits-print-80mm.BySp7XrN.png",c="/assets/splits-print-58mm.B9vl_JWp.png",u="/assets/settings-splits-printer.BZ7dbmY9.png",w="/assets/settings-splits-printer-usb.B1tzZo-8.png",f="/assets/settings-splits-printer-off.Gztwv_LU.png",m="/assets/edit-event-splits-print-station-printer.u5QArQXn.png",b="/assets/edit-event-splits-print-station.B6J8AsJ_.png",y="/assets/edit-event-splits-print-qr-global.DCNgAT2d.png",v="/assets/edit-event-splits-print-printing-off.D-cWc6JR.png",k="/assets/edit-event-splits-print-station-only.BziuDXLX.png",q="/assets/edit-event-splits-print.BPL3-TQX.png",T="/assets/download-card-print.CI_H_UHx.png",S="/assets/competitors-edit-splits-print.4LzVs7II.png",C=JSON.parse('{"title":"Printing splits","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/splits-printing.md","filePath":"user/running-the-event/splits-printing.md"}'),P={name:"user/running-the-event/splits-printing.md"};function A(x,t,_,E,W,R){const r=i("Mermaid");return e(),a("div",null,[t[1]||(t[1]=n('<h1 id="printing-splits" tabindex="-1">Printing splits <a class="header-anchor" href="#printing-splits" aria-label="Permalink to &quot;Printing splits&quot;">​</a></h1><p><strong>Audience:</strong> Organisers deciding what printing gear to bring, and timing operators running the download desk on the day.</p><p>This page covers what a printout contains, the two ways Manager can print one, how to choose between them (and how to run both), and what to do when nothing comes out.</p><blockquote><p><strong>Note:</strong> Everything here is about the <em>printed</em> slip. What a spectator sees on a phone or a TV is covered in <a href="./../screens/tv-screens">Leaderboard</a> and <a href="./../screens/info-screens">Event info screens</a>.</p></blockquote><h2 id="what-a-printout-contains" tabindex="-1">What a printout contains <a class="header-anchor" href="#what-a-printout-contains" aria-label="Permalink to &quot;What a printout contains&quot;">​</a></h2><p>The whole slip is rendered by the <strong>server</strong>, whichever printer it eventually comes out of. That is worth knowing up front: it means every printer at your event produces exactly the same slip, and the settings that decide what goes on it live in one place rather than on each laptop.</p><p><img src="'+g+'" alt="A splits print on 80 mm paper: the event name &quot;City Sprint Championships&quot; and date, the competitor&#39;s name Alex Johnson, club, class and course with length and climb, a large status OK and time 20:34, the check/start/finish times and card number, a table of eight controls with split and elapsed time, a Mistakes section listing controls 34 and 36 with total time lost 1:54, the class standings headed &quot;Current top 3 at 10:42am&quot; listing three places and the line &quot;Finished: 6 of 11&quot;, and a QR code headed &quot;Splits, Analysis &amp; Results&quot; with the caption &quot;Scan for full results&quot; above the meshO Manager logo."></p><p>Reading down the slip:</p><table tabindex="0"><thead><tr><th>Section</th><th>What it says</th><th>When it appears</th></tr></thead><tbody><tr><td><strong>Header</strong></td><td>Event name and date</td><td>Always</td></tr><tr><td><strong>Competitor</strong></td><td>Name, club, class, course, course length and climb</td><td>Always (club, class and course only when the competitor has them)</td></tr><tr><td><strong>Result</strong></td><td>Status and race time, in large type. Points and any penalty on a score course</td><td>Always</td></tr><tr><td><strong>Timing</strong></td><td>Check, start, finish, card number, and the SIAC battery voltage</td><td>Each line only when that time exists</td></tr><tr><td><strong>Splits</strong></td><td>One row per control: number, control code, leg time, elapsed time — then the finish row</td><td>When the card has been read</td></tr><tr><td><strong>Extra controls</strong></td><td>Punches that were not on the course</td><td>Only on a clean (OK) run that has some</td></tr><tr><td><strong>Mistakes</strong></td><td>The legs that cost time, and the total lost</td><td>When the analysis found time lost</td></tr><tr><td><strong>Class standings</strong></td><td>The current top 3, the runner&#39;s own place if they finished outside it, and how much of the class has finished</td><td>When the <strong>Print top 3 places</strong> setting is on and someone has a place</td></tr><tr><td><strong>QR code</strong></td><td>A heading, the code, and a caption</td><td>When the QR code is switched on and has an address</td></tr><tr><td><strong>Footer</strong></td><td>The meshO logo, or the words <em>meshO Manager</em></td><td>Always</td></tr></tbody></table><p>Three of those sections answer questions the operator would otherwise be asked at the desk. <strong>Mistakes</strong> heads off &quot;where did I lose it?&quot;, <strong>class standings</strong> heads off &quot;who won?&quot;, and the <strong>QR code</strong> heads off &quot;where do I see the full results?&quot;.</p><blockquote><p><strong>Tip:</strong> The standings <em>heading</em> is what stops a runner reading a provisional top 3 as a final result: it says <strong>Current top 3 at 10:42am</strong> while anyone in the class could still displace those places, and <strong>Final top 3</strong> once nobody can. Leave the section on.</p></blockquote><blockquote><p><strong>Note:</strong> The line beneath the places — <em>Finished: 6 of 11</em> — counts the runners who hold a <strong>place</strong> against everyone entered in the class. The two do not close the gap between them, and that is not an error: someone who mis-punched, retired, was disqualified, or was seen by the radio finish but has not downloaded yet is neither placed nor still out on the course. If you want to know who is actually still in the forest, that question is <a href="./safety-check">Safety check: accounting for everyone</a>, not this line.</p></blockquote><h3 id="paper-width" tabindex="-1">Paper width <a class="header-anchor" href="#paper-width" aria-label="Permalink to &quot;Paper width&quot;">​</a></h3><p>Manager lays the slip out for the roll it is printing on: <strong>80 mm</strong> (the standard width) or <strong>58 mm</strong>. The narrow roll fits the same information into fewer columns, so lines wrap more and the slip comes out longer.</p><p><img src="'+c+'" alt="The same splits print rendered for 58 mm paper: the same sections in a narrower column, with the event name wrapping across two lines and a smaller QR code."></p><p>Paper width is set <strong>per printer</strong>, not per event — once in Settings for the printers the server prints on, and on each download station for its own (see below).</p><h3 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h3><p>The slip is printed in whichever language you choose in <strong>Splits language</strong>, independently of the language the operator&#39;s browser is in. Left as <strong>Same as display language</strong> it follows the installation&#39;s default language, so an installation that switches language switches its splits prints with it. An event can name a different language of its own, which is what an international event needs.</p><h2 id="the-two-ways-to-print" tabindex="-1">The two ways to print <a class="header-anchor" href="#the-two-ways-to-print" aria-label="Permalink to &quot;The two ways to print&quot;">​</a></h2><p>Manager can print a slip from either end of the connection, and the difference matters when you are deciding what to buy and where to put it.</p><ul><li><strong>The server&#39;s printers.</strong> One or more printers, attached to the computer running Manager or reachable on the network. Each is given a name — <em>Left lane</em>, <em>Women&#39;s Elite</em>, <em>Public</em> — and each download station picks the one it wants its slips to come out on. A station that picks nothing uses whichever printer is marked the default.</li><li><strong>A station&#39;s own printer.</strong> A USB thermal printer plugged into a download laptop, printed straight from that laptop&#39;s browser. Set up per station, in that browser.</li></ul>',21)),(e(),h(p,null,{default:o(()=>[l(r,{id:"mermaid-202",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20one%5B%22One%20printer%20on%20the%20server%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20oneLap1%5B%22Download%20laptop%201%22%5D%20--%3E%20oneSrv%5B%22Manager%20server%22%5D%0A%20%20%20%20%20%20%20%20oneLap2%5B%22Download%20laptop%202%22%5D%20--%3E%20oneSrv%0A%20%20%20%20%20%20%20%20oneSrv%20--%3E%20onePrn(%5B%22Printer%22%5D)%0A%20%20%20%20end%0A%20%20%20%20subgraph%20each%5B%22A%20printer%20at%20each%20station%22%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20eachLap1%5B%22Download%20laptop%201%22%5D%20--%3E%20eachPrn1(%5B%22Printer%201%22%5D)%0A%20%20%20%20%20%20%20%20eachLap2%5B%22Download%20laptop%202%22%5D%20--%3E%20eachPrn2(%5B%22Printer%202%22%5D)%0A%20%20%20%20%20%20%20%20eachLap1%20--%3E%20eachSrv%5B%22Manager%20server%22%5D%0A%20%20%20%20%20%20%20%20eachLap2%20--%3E%20eachSrv%0A%20%20%20%20end%0A%20%20%20%20style%20onePrn%20fill%3A%23FF914D%2Ccolor%3A%23000000%0A%20%20%20%20style%20eachPrn1%20fill%3A%23FF914D%2Ccolor%3A%23000000%0A%20%20%20%20style%20eachPrn2%20fill%3A%23FF914D%2Ccolor%3A%23000000%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=n('<p>Both print the same slip, because both ask the server to render it. The difference is only where the paper comes out — and, as a consequence, how the tent works.</p><h2 id="choosing-your-setup" tabindex="-1">Choosing your setup <a class="header-anchor" href="#choosing-your-setup" aria-label="Permalink to &quot;Choosing your setup&quot;">​</a></h2><h3 id="one-printer-on-the-server" tabindex="-1">One printer on the server <a class="header-anchor" href="#one-printer-on-the-server" aria-label="Permalink to &quot;One printer on the server&quot;">​</a></h3><p>Everything prints in one place: next to the server, or wherever a network printer is parked.</p><table tabindex="0"><thead><tr><th>Advantages</th><th>Disadvantages</th></tr></thead><tbody><tr><td>One printer to buy, configure, feed with paper and troubleshoot</td><td>The slip comes out where the printer is, not where the runner is, so the collection point needs someone at it — or a rack the slips can be left in</td></tr><tr><td><strong>The download desk stays lean, and the queue keeps moving</strong> — see below</td><td>At peak, every lane&#39;s slips queue behind one printer, interleaved in whatever order downloads arrive</td></tr><tr><td>Any station can print, whatever browser or device it is running — including a tablet</td><td>If it jams or runs out, nothing prints anywhere until it is fixed</td></tr><tr><td>Set up once, in Settings, and it applies to every event on the server</td><td>A network printer needs a stable LAN and a fixed address to stay reachable</td></tr><tr><td>Nothing to configure on each download laptop, beyond naming which printer it prints on</td><td></td></tr></tbody></table><p><strong>The layout this buys you.</strong> Because the printer doesn&#39;t have to sit at the desk, downloading and collecting become two separate queues. Reading a card takes a few seconds, so a runner downloads and moves on immediately, and picks their slip up from a table at the far end of the tent — away from the readers, where they can read it and compare times without holding anyone up. The download lanes themselves need less space and less equipment: a laptop and a reader, no printer, no cable, no spare rolls under the table. On a busy day that is often worth more than having the slip in hand at the desk.</p><p><strong>Best for:</strong> club nights and smaller events, especially where the download laptop <em>is</em> the server — and equally, any event that would rather keep its download lanes clear and hand slips out at a separate collection table.</p><h3 id="a-printer-at-each-download-station" tabindex="-1">A printer at each download station <a class="header-anchor" href="#a-printer-at-each-download-station" aria-label="Permalink to &quot;A printer at each download station&quot;">​</a></h3><p>Each laptop drives the thermal printer plugged into it, and hands the slip straight over the desk.</p><table tabindex="0"><thead><tr><th>Advantages</th><th>Disadvantages</th></tr></thead><tbody><tr><td>The slip comes out beside the runner who just downloaded — no fetching, no mixing up, nobody staffing a collection table</td><td>A printer, a cable and a paper supply per lane</td></tr><tr><td>Capacity scales with lanes: four desks print four slips at once</td><td>The runner stays at the desk until their slip appears, and often reads it there — so the lane moves at the speed of the printing, not the reading</td></tr><tr><td>Nothing has to be carried anywhere, which suits lanes spread across separate tents</td><td>Needs <strong>Chrome or Edge</strong> on that laptop — Firefox cannot drive a USB printer even though it can read cards</td></tr><tr><td>A printer failing takes out one lane, not the whole tent</td><td>Needs a secure connection on any laptop that is not the server (the same HTTPS setup card download already needs)</td></tr><tr><td>No server printer needed at all, so the server can live in a box under the table</td><td>Set up by hand on each station, and stored in that browser — a different browser, or a fresh profile, starts unset</td></tr><tr><td>Each station picks its own paper width</td><td>On Windows, a printer already claimed by its own Windows driver has to be released before the browser can use it</td></tr><tr><td></td><td>A station that prints for itself <strong>always</strong> prints on download; there is no per-station switch for that</td></tr></tbody></table><p><strong>Best for:</strong> events with two or more download lanes where you want the slip handed over at the desk — and events whose lanes are spread out, or in separate tents, where a single collection table would mean carrying slips across the arena.</p><h3 id="both-together" tabindex="-1">Both together <a class="header-anchor" href="#both-together" aria-label="Permalink to &quot;Both together&quot;">​</a></h3><p>A printer on the server <em>and</em> printers on the busy stations is a supported combination, not a conflict — and it is what a larger event usually ends up with.</p><p>Manager keeps the two from fighting:</p><ul><li>A station that is printing for itself tells the server to skip its own printing for that download, so <strong>a slip is never printed twice</strong>.</li><li>If that station&#39;s printer is switched on but not actually connected — unplugged, or the browser was reloaded and the printer not re-selected — the server prints instead, so <strong>a slip is never dropped</strong>.</li></ul><table tabindex="0"><thead><tr><th>Advantages</th><th>Disadvantages</th></tr></thead><tbody><tr><td>Fast lanes print their own; the server&#39;s printer covers everything else</td><td>Two kinds of printer to keep working, and two places to look when one doesn&#39;t</td></tr><tr><td>Automatic fallback if a station&#39;s printer drops out</td><td>An operator reprinting from a station prints on <em>that station&#39;s</em> printer, which may not be the one they are standing next to</td></tr><tr><td>A printer at the enquiries desk can reprint for anyone without a lane&#39;s laptop</td><td></td></tr><tr><td>Lanes that need to keep moving can drop their own printer and fall back to the collection table, one switch at a time</td><td></td></tr></tbody></table><p><strong>Best for:</strong> regional and national events, and anywhere there is a results or enquiries desk separate from the download lanes.</p><blockquote><p><strong>Tip:</strong> Whichever you choose, bring a spare roll and put it beside the printer. The most common &quot;the printer has stopped&quot; call at an event is an empty roll.</p></blockquote><h2 id="setting-up-the-server-s-printer" tabindex="-1">Setting up the server&#39;s printer <a class="header-anchor" href="#setting-up-the-server-s-printer" aria-label="Permalink to &quot;Setting up the server&#39;s printer&quot;">​</a></h2><p>Open <strong>Settings → Splits printer</strong>. The top half of the page, <strong>Printer connection</strong>, is the printer — or printers — this server prints on.</p><p><img src="'+u+'" alt="Settings → Splits printer: the Printer connection section with &quot;Enable server splits printer&quot; on, Connection set to Network printer (TCP/IP) and Paper width 80 mm, then a Network printers list of three named rows — Left lane, Right lane and Enquiries desk — each with a host, a port, a Default radio and test and remove buttons, and an Add printer button below; then the Splits printer defaults section with switches for automatic printing, logo, top 3 places, splits language and the QR code fields."></p><ol><li>Turn on <strong>Enable server splits printer</strong>.</li><li>Choose the <strong>Connection</strong>: <ul><li><strong>Network printer (TCP/IP)</strong> — for printers with their own network address, or a print server. This works whatever operating system the server runs, and you can list as many printers as you have (see below).</li><li><strong>Directly attached printer (USB — Windows)</strong> — for a printer plugged into the server itself. Windows only, and one printer.</li></ul></li><li>Set the <strong>Paper width</strong> to match the roll.</li><li>Press <strong>Test print</strong>. A short test slip should come out; if it doesn&#39;t, the message under the button says what went wrong.</li></ol><h3 id="listing-your-network-printers" tabindex="-1">Listing your network printers <a class="header-anchor" href="#listing-your-network-printers" aria-label="Permalink to &quot;Listing your network printers&quot;">​</a></h3><p>A network connection is a <strong>list</strong>, not a single address, because an event usually has more printers than servers: one per download lane, one at enquiries, one for the announcer.</p><p>Press <strong>Add printer</strong> and fill in the row:</p><ul><li><strong>Name</strong> — what you call it. Use where it stands, not what it is: <em>Left lane</em>, <em>Right lane</em>, <em>Women&#39;s Elite</em>, <em>Public</em>. That name is what an operator picks from at their station, so <em>Epson TM-T20III #2</em> helps nobody standing in a tent. Leave it blank and the address is used as the name.</li><li><strong>Printer host / IP address</strong> and <strong>Port</strong> — how to reach it. 9100 is the usual raw-printing port. A row with no address is dropped when you save.</li><li><strong>Default</strong> — exactly one printer is the default. It is where a slip goes when nothing says otherwise: a station that has not picked a printer, and any print that isn&#39;t made at a station.</li><li>The <strong>printer button</strong> beside each row sends a test slip to <em>that</em> printer. Test each one as you name it — that is how you find out you have <em>Left lane</em> and <em>Right lane</em> the wrong way round while it still costs nothing.</li></ul><p>Renaming a printer later is safe: the stations pointed at it stay pointed at it. Deleting one is not quite — a station still set to it falls back to the default printer, so its slips keep coming out, just not where that operator expects. Tell the lane, or re-point it.</p><blockquote><p><strong>Note:</strong> Naming several printers does not, on its own, change where anything prints. Every station keeps using the default until someone at that station picks another — see <a href="#choosing-which-printer-a-station-prints-on">Choosing which printer a station prints on</a>.</p></blockquote><h3 id="a-printer-attached-to-the-server" tabindex="-1">A printer attached to the server <a class="header-anchor" href="#a-printer-attached-to-the-server" aria-label="Permalink to &quot;A printer attached to the server&quot;">​</a></h3><p><img src="'+w+'" alt="Settings → Splits printer with Connection set to &quot;Directly attached printer (USB — Windows)&quot;: a Printer dropdown showing an EPSON TM-T20III with a refresh button, and a Print language dropdown set to Epson ESC/POS."></p><p>There is one of these, not a list — it is the printer plugged into the server itself. Choosing it adds two fields:</p><ul><li><strong>Printer</strong> — the Windows printer to use. The refresh button beside it re-reads the list, for a printer plugged in after the page was opened.</li><li><strong>Print language</strong> — how the slip is sent: <ul><li><strong>Epson ESC/POS</strong> sends raw thermal-printer commands. Use this for a thermal printer.</li><li><strong>Windows driver (any printer)</strong> renders the slip as an image and prints it through the installed driver. Slower, but it works with any printer Windows can print to — including an ordinary office printer, if that is what you have.</li></ul></li></ul><h3 id="if-the-server-has-no-printer" tabindex="-1">If the server has no printer <a class="header-anchor" href="#if-the-server-has-no-printer" aria-label="Permalink to &quot;If the server has no printer&quot;">​</a></h3><p>Leave <strong>Enable server splits printer</strong> off. The connection fields collapse, but the <strong>Splits printer defaults</strong> stay — because they are also what a download station&#39;s own printer prints from.</p><p><img src="'+f+'" alt="Settings → Splits printer with the server printer switched off: only the Enable switch remains in the Printer connection section, while the Splits printer defaults below stay fully available."></p><p>Every default stays, <strong>Automatic print splits on download</strong> included — it is not a property of a printer but you saying whether a download prints without being asked, and a station printing on its own obeys it exactly as the server&#39;s printer does. It used to be hidden here, which left a station-only desk with no way to say otherwise.</p><h2 id="choosing-which-printer-a-station-prints-on" tabindex="-1">Choosing which printer a station prints on <a class="header-anchor" href="#choosing-which-printer-a-station-prints-on" aria-label="Permalink to &quot;Choosing which printer a station prints on&quot;">​</a></h2><p>Both of the station settings below live in <strong>Event details → Splits print</strong>, at the bottom of the tab, under <strong>Splits printing on this station</strong>. Both are set on the <strong>station</strong>, in that browser — not on the server, and not on the event. They apply to every event you open on that laptop, and they take effect the moment you change them, without saving the event.</p><p>If the server has more than one network printer, the station starts with a <strong>Print on</strong> dropdown:</p><p><img src="'+m+'" alt="The Splits print tab of Event details, scrolled to the Splits printing on this station section: a &quot;Print on&quot; dropdown showing &quot;Default printer (Left lane)&quot; with the list open on Left lane, Right lane and Enquiries desk, and a Test print button beside it."></p><ul><li>Leave it on <strong>Default printer</strong> and this station&#39;s slips come out wherever the default is — which is what every station did before there were several to choose from.</li><li>Pick a name and this station&#39;s slips come out there instead: its automatic prints on download, and anything an operator reprints from it.</li><li>The <strong>printer button</strong> beside it sends a test slip to the printer you have picked. Use it: the point of the setting is that the slip lands beside the operator, and the only way to be sure is to watch one come out.</li></ul><p>The dropdown is hidden when there is nothing to choose between — one network printer, or none.</p><blockquote><p><strong>Note:</strong> Each station makes this choice for itself, so two lanes sharing a laptop share a printer, and the same operator at a different laptop is set separately. If a lane&#39;s slips are coming out in the wrong tent, that lane&#39;s browser is where the setting is.</p></blockquote><h2 id="setting-up-a-printer-on-a-download-station" tabindex="-1">Setting up a printer on a download station <a class="header-anchor" href="#setting-up-a-printer-on-a-download-station" aria-label="Permalink to &quot;Setting up a printer on a download station&quot;">​</a></h2><p>This one is set on the <strong>station</strong> too, and it lives in that browser — so do it at the laptop that has the printer.</p><p>Open the event, then <strong>Event details → Splits print</strong>, and scroll to <strong>Splits printing on this station</strong>.</p><p><img src="'+b+'" alt="The Splits print tab of Event details, scrolled to the bottom: the QR code fields for a customised event, then the Splits printing on this station section with a greyed-out &quot;Print on&quot; dropdown, &quot;Print splits on this station&quot; switched on, a Paper width dropdown set to 80 mm and a Select printer button."></p><ol><li>Turn on <strong>Print splits on this station</strong>.</li><li>Choose the <strong>Paper width</strong> for the roll in <em>this</em> printer.</li><li>Press <strong>Select printer</strong>. The browser shows its USB device chooser — pick the printer and confirm.</li><li>The button is replaced by a green <strong>Printer connected</strong> chip, a <strong>Test print</strong> button and a <strong>Disconnect</strong> button. Press <strong>Test print</strong> and check a slip comes out.</li></ol><p>What to expect from this setting:</p><ul><li><strong>It is remembered on this computer</strong>, in this browser, and applies to <strong>every event</strong> you open here — not just the one whose dialog you set it in.</li><li><strong>It does not affect anyone else.</strong> Other stations, and the server&#39;s own printers, are untouched.</li><li><strong>Downloads on this station print here automatically</strong>, and the server&#39;s printers are skipped for them — including whichever one <strong>Print on</strong> names, which is why that dropdown greys out while this switch is on.</li><li><strong>A reload needs one action to come back.</strong> The browser remembers which printer you chose, but the live connection to it does not survive a page reload. Opening <strong>Event details → Splits print</strong> re-establishes it silently, and so does a <strong>Test print</strong> — until then this station&#39;s downloads print on the server&#39;s printer instead, or, if there is no server printer, not at all.</li></ul><blockquote><p><strong>Warning:</strong> That last point is the one to build a habit around. If you reload the page, or the laptop wakes from sleep and the page reloads with it, open <strong>Event details → Splits print</strong> once and check the green <strong>Printer connected</strong> chip is there before the next runner comes in.</p></blockquote><h3 id="requirements-and-the-two-things-that-usually-block-it" tabindex="-1">Requirements, and the two things that usually block it <a class="header-anchor" href="#requirements-and-the-two-things-that-usually-block-it" aria-label="Permalink to &quot;Requirements, and the two things that usually block it&quot;">​</a></h3><p>Printing to a USB printer from the browser uses the <strong>WebUSB API</strong>, which needs:</p><ul><li><strong>Chrome or Edge.</strong> Firefox has the Web Serial API that card download needs, but not WebUSB — so a Firefox download station can read cards and cannot print on its own printer. Use Chrome or Edge on any laptop that is to have its own printer.</li><li><strong>A secure connection.</strong> On the computer running the server, opening Manager at <code>http://localhost:5154/manager</code> is enough. On any other laptop, HTTPS has to be on and meshO&#39;s certificate trusted — the same one-off setup card download already requires. See <a href="./../reference/https-and-certificates">HTTPS and certificates</a>. If it isn&#39;t in place, the section says so instead of offering the printer.</li></ul><p>The other blocker is Windows-specific and has a clear message: <strong>Windows is using this printer through its own driver, so the browser cannot claim it.</strong> If your thermal printer has been installed as a Windows printer, Windows holds it and will not let the browser take it. Remove the Windows driver for that printer (or switch it to WinUSB) and select it again.</p><blockquote><p><strong>Note:</strong> If you would rather not deal with any of that, the printer can be plugged into the <em>server</em> instead and shared with every station — that is the <a href="#setting-up-the-server-s-printer">server printer</a> setup above, and on Windows it can use the ordinary driver.</p></blockquote><h2 id="what-each-printout-contains-the-defaults" tabindex="-1">What each printout contains: the defaults <a class="header-anchor" href="#what-each-printout-contains-the-defaults" aria-label="Permalink to &quot;What each printout contains: the defaults&quot;">​</a></h2><p>The lower half of <strong>Settings → Splits printer</strong> — <strong>Splits printer defaults</strong> — decides what goes on a printout, for every event on this server, on whichever printer prints it.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Automatic print splits on download</strong></td><td>A slip is printed for every download that produces a result, without anyone pressing anything. It governs whichever printer would print it — the server&#39;s, and a station printing on its own — so turning it off means no download prints by itself anywhere</td></tr><tr><td><strong>Print meshO logo</strong></td><td>The logo at the foot of the slip. Off prints the words <em>meshO Manager</em> instead</td></tr><tr><td><strong>Print top 3 places on splits</strong></td><td>Ends each slip with the current top 3 in the runner&#39;s class, plus their own place when they finished outside it</td></tr><tr><td><strong>Splits language</strong></td><td>The language the slip is printed in</td></tr><tr><td><strong>Print QR code</strong></td><td>Ends each slip with a QR code — see <a href="#the-qr-code">The QR code</a></td></tr></tbody></table><p>With auto-print off, nothing prints by itself at all: no slip, and no countdown on a mis-punch. Printing then happens only when you ask for it — see <a href="#printing-by-hand-and-reprinting">Printing by hand, and reprinting</a>.</p><p>A slip is printed automatically for every result <strong>except</strong> one with nothing to say: an unknown or unassigned card, a repeat of a download already recorded, a card whose owner already has a result, and a competitor with no class. Mis-punches, DNFs and disqualifications all still print — a runner with a problem is exactly the one who wants the slip.</p><h2 id="mis-punches-wait-before-they-print" tabindex="-1">Mis-punches wait before they print <a class="header-anchor" href="#mis-punches-wait-before-they-print" aria-label="Permalink to &quot;Mis-punches wait before they print&quot;">​</a></h2><p>Most mis-punches at a download desk are not mis-punches. The runner went round a different course to the one they entered; you change their class, the download is re-evaluated, and the corrected slip prints. Which means the <strong>MP</strong> slip that came out the instant the card was read only ever went in the bin. Over a weekend that is a lot of paper.</p><p>So a mis-punch slip waits. <strong>Settings → Splits printer → Splits printer defaults</strong> has two controls for it: <strong>Hold a mis-punch printout</strong>, on by default, and <strong>Hold it for</strong> — 20 seconds by default, up to a minute. Switch the hold off and a mis-punch prints the moment the card is read, as every other verdict does. Both apply whichever printer the slip comes out of, so a station printing on its own USB printer counts down the same window as the server.</p><p><strong>An event can take its own line on the hold</strong>, under <strong>Event details → Splits print → Hold a mis-punch printout</strong> — the usual three-way choice of <em>Use global setting</em>, <em>On for this event</em>, <em>Off for this event</em>. This is the one worth reaching for: whether the wait suits a desk depends on how that desk works. An event handing each runner their slip at the counter does not want twenty seconds of nothing between the beep and the paper; one correcting wrong-course entries all afternoon does. <em>How long</em> it waits is not overridable — that belongs to the desk, like paper width, not to the event.</p><p>While it waits, the result banner draws the window as an arc around a small printer icon, emptying as it closes. The arc only ever appears where a slip is actually coming and is actually waiting: with <strong>Automatic print splits on download</strong> off nothing prints by itself, and with the hold off the slip prints at once — either way there is nothing to wait for and nothing drawn. Both read the event&#39;s override before the installation&#39;s setting.</p><table tabindex="0"><thead><tr><th>What you do inside the window</th><th>What comes out</th></tr></thead><tbody><tr><td><strong>Change the class</strong> — or anything else that re-evaluates the download</td><td>The <strong>corrected</strong> slip, immediately. Nothing prints later than it used to; only the wasted sheet stops being printed</td></tr><tr><td><strong>Press the ✕</strong> beside the countdown, or <strong>open a dialog about that runner</strong></td><td>Nothing at all — see below</td></tr><tr><td><strong>Unassign or delete</strong> the download</td><td>Nothing. There is no longer a result for the slip to describe</td></tr><tr><td><strong>Print the slip by hand</strong></td><td>Your slip, once. The waiting copy is dropped rather than following it out</td></tr><tr><td>Nothing</td><td>The mis-punch slip, at the end of the window. A genuine mis-punch nobody touches still gets its slip</td></tr></tbody></table><blockquote><p><strong>Note:</strong> Changing the class to another one the punches <em>also</em> don&#39;t fit starts the window again — you haven&#39;t finished correcting yet.</p></blockquote><h3 id="ending-the-wait-with-nothing-printed" tabindex="-1">Ending the wait with nothing printed <a class="header-anchor" href="#ending-the-wait-with-nothing-printed" aria-label="Permalink to &quot;Ending the wait with nothing printed&quot;">​</a></h3><p>Sometimes there is nothing to correct: the runner really did miss a control, and the slip is a foregone conclusion you&#39;d rather not wait for — or not print at all. The <strong>✕</strong> beside the countdown ends the wait there and then, and prints nothing.</p><p><strong>Opening a dialog about that runner does the same.</strong> Clicking the banner to open their result, opening a download&#39;s detail dialog from the history table, clicking a name in that table, or opening the controls the dashboard tile dropped into a dialog — each ends that runner&#39;s wait. Opening them is you taking the correction in hand, and that is open-ended: reading the splits, choosing a class, thinking about it for a minute. A slip printing out from under you mid-edit is exactly the wasted sheet the wait exists to stop.</p><p>If the change you then make re-evaluates the download, the corrected slip prints as normal. If you close the dialog having changed nothing and you <em>do</em> want the mis-punch slip after all, print it with the printer button on that download&#39;s row — see <a href="#printing-by-hand-and-reprinting">Printing by hand, and reprinting</a>.</p><p>The wait is per runner, not one at a time. Cards keep arriving while you work, and cancelling — or opening a dialog about — one runner never takes the slip of the next one, still standing at the desk waiting for theirs.</p><blockquote><p><strong>Note:</strong> Only mis-punches ever wait. Every other verdict prints exactly as it always did.</p></blockquote><h2 id="per-event-overrides" tabindex="-1">Per-event overrides <a class="header-anchor" href="#per-event-overrides" aria-label="Permalink to &quot;Per-event overrides&quot;">​</a></h2><p>Most of those defaults can be overridden for a single event, under <strong>Event details → Splits print</strong> — including whether a mis-punch printout waits, covered in <a href="#mis-punches-wait-before-they-print">Mis-punches wait before they print</a> above. This is where a low-key club night turns the QR code off, or an international event prints in a different language, without changing what every other event does.</p><p><img src="'+y+'" alt="The Splits print tab of Event details: a Per-event overrides section with five dropdowns — Automatic print splits on download, Hold a mis-punch printout, Print meshO logo, Print top 3 places and Splits language — each reading &quot;Use global setting&quot; with the current value in brackets, then a QR code section also set to &quot;Use global setting (on)&quot; and showing the installation&#39;s URL."></p><p>Each override is a three-way choice, and the first option names what the installation currently does — so you can see what you would be inheriting before you decide to override it:</p><ul><li><strong>Use global setting (on/off)</strong> — follow Settings. Change the setting there later and this event follows.</li><li><strong>On for this event</strong> / <strong>Off for this event</strong> — this event goes its own way, whatever Settings says.</li></ul><p>The QR code picker in the same tab works the same way but has more to say than on or off, so its middle option is <strong>Customise for this event</strong> — see <a href="#the-qr-code">The QR code</a>.</p><blockquote><p><strong>Note:</strong> Paper width is deliberately not here. It belongs to a printer, not an event, so it is set on the server&#39;s printer and on each station.</p></blockquote><h3 id="when-nothing-is-printing" tabindex="-1">When nothing is printing <a class="header-anchor" href="#when-nothing-is-printing" aria-label="Permalink to &quot;When nothing is printing&quot;">​</a></h3><p>If the server&#39;s printer is switched off <em>and</em> this station isn&#39;t printing either, the tab says so and holds the overrides back rather than letting you configure a printout nothing produces.</p><p><img src="'+v+'" alt="The Splits print tab with a notice reading &quot;Nothing prints splits for this event: the splits printer is switched off in Settings → Splits printer, and this station is not printing either. Switch on either one and the settings for what a printout contains appear here.&quot;, above the Splits printing on this station switch."></p><p>Turn on either one and the overrides appear. With only this station printing, they come back with a note saying the server&#39;s printer is off — the settings still apply, because the server still renders the slip.</p><p><img src="'+k+'" alt="The Splits print tab with the server printer off but this station&#39;s printing switched on: the per-event overrides are shown again, with a caption explaining that the server&#39;s splits printer is switched off and these settings reach this station&#39;s printer."></p><h2 id="the-qr-code" tabindex="-1">The QR code <a class="header-anchor" href="#the-qr-code" aria-label="Permalink to &quot;The QR code&quot;">​</a></h2><p>A QR code at the foot of the slip is the shortest route from a paper result to the full results on a phone. Scanned, it opens whatever address you configure — normally this server&#39;s own spectator page, with the competitor&#39;s id in it, so it lands on <em>their</em> result rather than the front page.</p><p>Four things make it up, and only the address has to be filled in:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Print QR code</strong></td><td>The switch. Off prints no code, even with an address configured — so you can keep the address on file between events</td></tr><tr><td><strong>QR code URL</strong></td><td>What the code encodes. Placeholders <code>{competitorId}</code>, <code>{eventId}</code> and <code>{cardNumber}</code> are filled in per runner</td></tr><tr><td><strong>QR code heading</strong></td><td>The line printed above the code. Left empty, a standard heading is printed, translated with the rest of the slip</td></tr><tr><td><strong>QR code caption</strong></td><td>The line printed below the code. Left empty, nothing is printed there</td></tr></tbody></table><p><strong>Use this server&#39;s spectator URL</strong> fills the address in for you, with the card number as the parameter. That is the right answer for most events; type your own address only if results are published somewhere else.</p><p>An event can take its own line on all of this. Under <strong>Event details → Splits print</strong>, the <strong>QR code</strong> picker offers:</p><ul><li><strong>Use global setting (on/off)</strong> — what Settings says, with the installation&#39;s address spelled out underneath.</li><li><strong>Customise for this event</strong> — print a code, with this event&#39;s own address and wording.</li><li><strong>Disable for this event</strong> — no code on this event&#39;s slips, whatever Settings says.</li></ul><p><img src="'+q+'" alt="The Splits print tab with the QR code set to &quot;Customise for this event&quot;, showing a QR code URL field pre-filled with this server&#39;s spectator address, a &quot;Use this server&#39;s spectator URL&quot; button, the supported placeholders listed beside it, and a QR code heading field."></p><p>In <strong>Customise for this event</strong>, each of the three fields is independent: fill in only the heading and the event keeps the installation&#39;s address and caption. A field left empty inherits; it does not blank the line.</p><blockquote><p><strong>Tip:</strong> A custom heading is a good place for the club&#39;s or event&#39;s own words — <em>Full results and analysis</em>, or the name of the series. Leave it empty at an international event: the standard heading is translated with the rest of the slip, and your own words are not.</p></blockquote><h2 id="printing-by-hand-and-reprinting" tabindex="-1">Printing by hand, and reprinting <a class="header-anchor" href="#printing-by-hand-and-reprinting" aria-label="Permalink to &quot;Printing by hand, and reprinting&quot;">​</a></h2><p>Automatic printing covers the normal case. Two places print on demand — for a slip that jammed, a runner who came back for another copy, or an event that prints only on request.</p><p><strong>From the download history.</strong> Every row on the <strong>Download card</strong> page has a printer button that prints that download&#39;s slip.</p><p><img src="'+T+'" alt="The Card downloads history on the Download card page, with three rows — Jordan Lee (MP), Sam Williams (OK) and Alex Johnson (OK) — each ending in a printer button."></p><p><strong>From the competitor.</strong> Open a competitor and choose the <strong>Splits print</strong> tab. It shows the slip exactly as it would print, rendered by the server, with a <strong>Print</strong> button underneath.</p><p><img src="'+S+'" alt="The Edit competitor dialog for Alex Johnson on the Splits print tab, showing a preview of the splits print — event name, competitor, status OK and time 20:34, timing lines — with a Print button at the bottom left."></p><p>That preview is worth using while you set printing up: it shows the effect of every setting on this page — logo, top 3, language, QR code — without spending any paper.</p><p>Both buttons print on <strong>this station&#39;s</strong> printer if it is printing for itself, and on the server&#39;s printer otherwise.</p><h2 id="when-nothing-prints" tabindex="-1">When nothing prints <a class="header-anchor" href="#when-nothing-prints" aria-label="Permalink to &quot;When nothing prints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What it usually is</th></tr></thead><tbody><tr><td>No printer buttons anywhere</td><td>Nothing is set up to print: the server&#39;s printer is off and this station isn&#39;t printing either</td></tr><tr><td>Nothing prints on download, but printing by hand works</td><td><strong>Automatic print splits on download</strong> is off — check Settings, and the event&#39;s own override</td></tr><tr><td>A station prints nothing, the server prints everything</td><td>The station&#39;s printer is switched on but not connected. Reconnect it with <strong>Select printer</strong>; the server has been covering for it</td></tr><tr><td>Two slips per runner</td><td>Two stations are set to print for the same downloads, or a slip is being printed by hand as well. A station that is properly connected suppresses the server automatically, so this points at a second station rather than at the server</td></tr><tr><td><strong>This browser cannot use a USB printer</strong></td><td>The station is on Firefox or Safari. Use Chrome or Edge</td></tr><tr><td><strong>Needs a secure connection</strong></td><td>HTTPS isn&#39;t set up on this laptop — see <a href="./../reference/https-and-certificates">HTTPS and certificates</a></td></tr><tr><td><strong>Windows is using this printer through its own driver</strong></td><td>Remove the Windows driver for that printer, or switch it to WinUSB, then select it again</td></tr><tr><td>A message that the USB device does not look like a printer</td><td>The wrong device was picked in the chooser — try again and pick the printer</td></tr><tr><td>The test print fails with a connection error</td><td>For a network printer, check the address and port, and that it is on the same network. Most thermal printers print their own address if you hold the feed button while powering on</td></tr><tr><td>Slips print, but the layout is wrong</td><td>The paper width doesn&#39;t match the roll. Set it on the printer that printed the slip: Settings for the server&#39;s, the Splits print tab for a station&#39;s</td></tr><tr><td>A runner&#39;s slip is blank or missing sections</td><td>Sections appear only when there is something to say — a competitor with no class, or a card that has not been read, has nothing to print</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./card-download">Downloading cards</a> — the download that triggers a printout</li><li><a href="./../reference/https-and-certificates">HTTPS and certificates</a> — needed on any download station that prints on its own printer</li><li><a href="./../reference/settings">Settings reference</a> — every settings page, including this one</li><li><a href="./resolving-issues">Resolving issues on the day</a> — the wider on-the-day troubleshooting page</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — what the status on the slip means</li><li><a href="./../reference/multi-operator-setup">Multi-operator setup</a> — running more than one download station</li></ul>',108))])}const I=s(P,[["render",A]]);export{C as __pageData,I as default};
